let menuCatalogue=[];
let menuCategories=[];
let weeklySelection=new Set();
let menuItemOrder=[];
let itemToOpen='';
const pendingPhotos=new Map();
const menuWorkerUrl=String(window.COOKIES_CAKES_MENU_WORKER_URL||'').replace(/\/$/,'');
const menuDataUrl=String(window.COOKIES_CAKES_MENU_DATA_URL||'').trim();
const refreshButton=document.querySelector('#refresh-menu');
const loadStatus=document.querySelector('#load-status');
const editor=document.querySelector('#editor');
const libraryMount=document.querySelector('#library-list');
const itemsMount=document.querySelector('#items');
const itemTemplate=document.querySelector('#item-template');
const saveStatus=document.querySelector('#save-status');
const emptyState=document.querySelector('#empty-state');
const activeCount=document.querySelector('#active-count');
const addCategoryButton=document.querySelector('#add-category');
const starterCatalogue=[{id:'example-cake',title:'Example cake',category:'Cakes',description:"A short description of this week's delicious offering can go here.",price:'£4.00',image:'',glutenFree:false,vegan:false},{id:'example-treat',title:'Example treat',category:'Treats',description:"A short description of this week's delicious offering can go here.",price:'£4.00',image:'',glutenFree:false,vegan:false}];

function setStatus(element,message,isError=false){element.textContent=message;element.style.color=isError?'#9a254d':'';}
function makeId(){return `item-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;}
function cleanCategory(value){return String(value||'').replace(/\s+/g,' ').trim();}
function normalisePrice(value){const entered=String(value||'').trim();if(!entered)return'';const amount=entered.replace(/[£,\s]/g,'');if(!/^\d+(\.\d{0,2})?$/.test(amount))return entered;return `£${Number(amount).toFixed(2)}`;}
function normaliseItem(item){return{id:item.id||makeId(),title:item.title||'',category:cleanCategory(item.category)||'Other',description:item.description||'',price:normalisePrice(item.price),image:item.image||'',glutenFree:Boolean(item.glutenFree),vegan:Boolean(item.vegan)};}
function normaliseCategories(categories,catalogue){const result=[];const seen=new Set();const add=value=>{const name=cleanCategory(value);const key=name.toLocaleLowerCase();if(name&&!seen.has(key)){seen.add(key);result.push(name);}};(Array.isArray(categories)?categories:[]).forEach(add);catalogue.forEach(item=>add(item.category));if(!result.length)add('Other');return result;}
function ensureCategory(value){const name=cleanCategory(value)||'Other';const existing=menuCategories.find(category=>category.toLocaleLowerCase()===name.toLocaleLowerCase());if(existing)return existing;menuCategories.push(name);return name;}
function normaliseMenuOrder(order,catalogue,selection){const known=new Set(catalogue.map(item=>item.id));const result=[];const seen=new Set();const add=id=>{if(known.has(id)&&!seen.has(id)){seen.add(id);result.push(id);}};(Array.isArray(order)?order:[]).forEach(add);(Array.isArray(selection)?selection:[]).forEach(add);catalogue.forEach(item=>add(item.id));return result;}
function normaliseMenuState(){menuCategories=normaliseCategories(menuCategories,menuCatalogue);menuCatalogue.forEach(item=>{item.category=ensureCategory(item.category);});menuItemOrder=normaliseMenuOrder(menuItemOrder,menuCatalogue,[...weeklySelection]);}
function assignmentFrom(source,name){const match=source.match(new RegExp(`window\\.${name}\\s*=\\s*([\\s\\S]*?);\\s*(?=window\\.|$)`));return match?Function(`"use strict";return (${match[1]});`)():undefined;}
function readMenuData(source){const catalogue=assignmentFrom(source,'menuCatalogue');const selection=assignmentFrom(source,'weeklyMenuSelection');const categories=assignmentFrom(source,'menuCategories');const order=assignmentFrom(source,'menuItemOrder');if(Array.isArray(catalogue)){const savedCatalogue=catalogue.map(normaliseItem);const savedSelection=Array.isArray(selection)?selection:[];return{catalogue:savedCatalogue,selection:savedSelection,categories:normaliseCategories(categories,savedCatalogue),order:normaliseMenuOrder(order,savedCatalogue,savedSelection)};}const legacy=assignmentFrom(source,'weeklyMenuItems');if(Array.isArray(legacy)){const legacyCatalogue=legacy.map(normaliseItem);const legacySelection=legacyCatalogue.map(item=>item.id);return{catalogue:legacyCatalogue,selection:legacySelection,categories:normaliseCategories(categories,legacyCatalogue),order:legacySelection};}const starterSelection=starterCatalogue.map(item=>item.id);return{catalogue:starterCatalogue,selection:starterSelection,categories:normaliseCategories([],starterCatalogue),order:starterSelection};}
function updateItemFromCard(card){const item=menuCatalogue.find(entry=>entry.id===card.dataset.id);if(!item)return;item.title=card.querySelector('[name="title"]').value;item.category=ensureCategory(card.querySelector('[name="category"]').value);item.description=card.querySelector('[name="description"]').value;item.price=card.querySelector('[name="price"]').value;item.glutenFree=card.querySelector('[name="glutenFree"]').checked;item.vegan=card.querySelector('[name="vegan"]').checked;}
function syncActiveEdits(){itemsMount.querySelectorAll('.item-card').forEach(updateItemFromCard);}
function addCategory(){const requested=window.prompt('Name the new category, for example “Cookies” or “Brownies”.');if(requested===null)return;const name=cleanCategory(requested);if(!name){setStatus(saveStatus,'Please enter a category name.',true);return;}syncActiveEdits();const alreadyExists=menuCategories.some(category=>category.toLocaleLowerCase()===name.toLocaleLowerCase());const category=ensureCategory(name);renderLibrary();renderActiveItems();setStatus(saveStatus,alreadyExists?`“${category}” is already in your category list.`:`Added “${category}”. You can now choose it from an item’s Category dropdown.`);}
function renameCategory(category){const requested=window.prompt(`Rename “${category}” to:`,category);if(requested===null)return;const name=cleanCategory(requested);if(!name){setStatus(saveStatus,'Please enter a category name.',true);return;}if(name.toLocaleLowerCase()===category.toLocaleLowerCase())return;if(menuCategories.some(entry=>entry!==category&&entry.toLocaleLowerCase()===name.toLocaleLowerCase())){setStatus(saveStatus,`“${name}” already exists. Choose a different name.`,true);return;}syncActiveEdits();menuCategories=menuCategories.map(entry=>entry===category?name:entry);menuCatalogue.forEach(item=>{if(item.category===category)item.category=name;});renderLibrary();renderActiveItems();setStatus(saveStatus,`Renamed “${category}” to “${name}”.`);}
function removeCategory(category){syncActiveEdits();const categoryItems=menuCatalogue.filter(item=>item.category===category);let replacement;if(categoryItems.length){let alternatives=menuCategories.filter(entry=>entry!==category);if(!alternatives.length){ensureCategory('Other');alternatives=menuCategories.filter(entry=>entry!==category);}const requested=window.prompt(`“${category}” contains ${categoryItems.length} saved item${categoryItems.length===1?'':'s'}. Move them to one of these categories before removing it:\n${alternatives.join(', ')}`,alternatives[0]);if(requested===null)return;replacement=alternatives.find(entry=>entry.toLocaleLowerCase()===cleanCategory(requested).toLocaleLowerCase());if(!replacement){setStatus(saveStatus,'Choose one of the categories shown to move the saved items safely.',true);return;}if(!window.confirm(`Move ${categoryItems.length} saved item${categoryItems.length===1?'':'s'} to “${replacement}” and remove “${category}”?`))return;categoryItems.forEach(item=>{item.category=replacement;});}else if(!window.confirm(`Remove the empty “${category}” category?`)){return;}menuCategories=menuCategories.filter(entry=>entry!==category);normaliseMenuState();renderLibrary();renderActiveItems();setStatus(saveStatus,replacement?`Moved the saved items to “${replacement}” and removed “${category}”.`:`Removed “${category}”.`);}
function renderLibrary(){normaliseMenuState();libraryMount.innerHTML='';menuCategories.forEach(category=>{const group=document.createElement('section');group.className='category-group';const titleRow=document.createElement('div');titleRow.className='category-title-row';const heading=document.createElement('h4');heading.textContent=category;const actions=document.createElement('div');actions.className='category-actions';const renameButton=document.createElement('button');renameButton.className='rename-category';renameButton.type='button';renameButton.textContent='Rename';renameButton.addEventListener('click',()=>renameCategory(category));const removeButton=document.createElement('button');removeButton.className='remove-category';removeButton.type='button';removeButton.textContent='Remove';removeButton.setAttribute('aria-label',`Remove ${category} category`);removeButton.addEventListener('click',()=>removeCategory(category));actions.append(renameButton,removeButton);titleRow.append(heading,actions);group.append(titleRow);const categoryItems=menuCatalogue.filter(item=>item.category===category).sort((a,b)=>a.title.localeCompare(b.title));if(!categoryItems.length){const empty=document.createElement('p');empty.className='category-empty';empty.textContent='No saved items yet.';group.append(empty);}categoryItems.forEach(item=>{const label=document.createElement('label');label.className='library-item';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=weeklySelection.has(item.id);checkbox.addEventListener('change',()=>{syncActiveEdits();if(checkbox.checked)weeklySelection.add(item.id);else weeklySelection.delete(item.id);renderLibrary();renderActiveItems();});const title=document.createElement('span');title.textContent=item.title||'Untitled item';label.append(checkbox,title);group.append(label);});libraryMount.append(group);});}
function populateCategorySelect(select,currentCategory){const selected=ensureCategory(currentCategory);select.innerHTML='';menuCategories.forEach(category=>{const option=document.createElement('option');option.value=category;option.textContent=category;select.append(option);});select.value=selected;}
function imagePathFor(item,file){const extension=(file.name.match(/\.[a-zA-Z0-9]+$/)||['.jpg'])[0].toLowerCase();const safeTitle=(item.title||'menu-item').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'menu-item';return `images/${Date.now()}-${item.id.replace(/[^a-z0-9-]/gi,'')}-${safeTitle}${extension}`;}
function createActiveCard(item){const fragment=itemTemplate.content.cloneNode(true);const card=fragment.querySelector('.item-card');card.dataset.id=item.id;const titleInput=card.querySelector('[name="title"]');const summaryTitle=card.querySelector('.item-summary-title');const updateSummary=()=>{summaryTitle.textContent=titleInput.value.trim()||'Untitled item';};titleInput.value=item.title;updateSummary();card.open=item.id===itemToOpen;if(card.open)itemToOpen='';const activeIndex=activeItemsInOrder().findIndex(entry=>entry.id===item.id);const activeLength=activeItemsInOrder().length;card.querySelector('.move-up').disabled=activeIndex===0;card.querySelector('.move-down').disabled=activeIndex===activeLength-1;card.querySelector('.move-up').addEventListener('click',()=>moveItem(item.id,-1));card.querySelector('.move-down').addEventListener('click',()=>moveItem(item.id,1));populateCategorySelect(card.querySelector('[name="category"]'),item.category);card.querySelector('[name="description"]').value=item.description;card.querySelector('[name="price"]').value=item.price;card.querySelector('[name="glutenFree"]').checked=item.glutenFree;card.querySelector('[name="vegan"]').checked=item.vegan;const photoName=card.querySelector('.photo-name');photoName.textContent=pendingPhotos.has(item.id)?`New photo: ${pendingPhotos.get(item.id).file.name}`:(item.image?`Current photo: ${item.image}`:'No photo selected');card.querySelectorAll('input[type="text"],textarea').forEach(input=>input.addEventListener('input',()=>{updateItemFromCard(card);if(input===titleInput)updateSummary();}));card.querySelector('[name="price"]').addEventListener('blur',event=>{event.target.value=normalisePrice(event.target.value);updateItemFromCard(card);});card.querySelectorAll('input[type="checkbox"]').forEach(input=>input.addEventListener('change',()=>updateItemFromCard(card)));titleInput.addEventListener('change',()=>{updateItemFromCard(card);updateSummary();renderLibrary();});card.querySelector('[name="category"]').addEventListener('change',()=>{updateItemFromCard(card);renderLibrary();});card.querySelector('[name="image"]').addEventListener('change',async event=>{const sourceFile=event.target.files[0];event.target.value='';if(!sourceFile)return;try{const file=await window.CookiesCakesImageCropper.cropImage(sourceFile);const path=imagePathFor(item,file);pendingPhotos.set(item.id,{file,path});item.image=path;photoName.textContent=`Cropped photo ready: ${file.name}`;}catch(error){if(error?.name!=='ImageCropCancelled'){setStatus(saveStatus,error.message||'Could not crop that photo.',true);}}});card.querySelector('.remove-item').addEventListener('click',()=>{if(!window.confirm(`Remove “${item.title||'this item'}” permanently from your menu library?`))return;menuCatalogue=menuCatalogue.filter(entry=>entry.id!==item.id);weeklySelection.delete(item.id);pendingPhotos.delete(item.id);renderLibrary();renderActiveItems();});itemsMount.append(card);}
function activeItemsInOrder(){return menuItemOrder.filter(id=>weeklySelection.has(id)).map(id=>menuCatalogue.find(item=>item.id===id)).filter(Boolean);}
function setActiveOrder(activeOrder){let index=0;menuItemOrder=menuItemOrder.map(id=>weeklySelection.has(id)?activeOrder[index++]:id);}
function saveDragOrder(){setActiveOrder([...itemsMount.querySelectorAll('.item-card')].map(entry=>entry.dataset.id));setStatus(saveStatus,'Menu order updated. Publish when you are ready.');}
function moveItem(itemId,direction){syncActiveEdits();const order=activeItemsInOrder().map(item=>item.id);const index=order.indexOf(itemId);const next=index+direction;if(index<0||next<0||next>=order.length)return;[order[index],order[next]]=[order[next],order[index]];setActiveOrder(order);renderActiveItems();setStatus(saveStatus,'Menu order updated. Publish when you are ready.');}
function renderActiveItems(){itemsMount.innerHTML='';const activeItems=activeItemsInOrder();activeItems.forEach(createActiveCard);emptyState.hidden=activeItems.length>0;activeCount.textContent=`${activeItems.length} active this week`;}
function addNewItem(position='top'){syncActiveEdits();const item=normaliseItem({id:makeId(),title:'New menu item',category:menuCategories[0]||'Other',description:'',price:'',image:'',glutenFree:false,vegan:false});item.category=ensureCategory(item.category);itemToOpen=item.id;menuCatalogue.push(item);weeklySelection.add(item.id);if(position==='bottom')menuItemOrder.push(item.id);else menuItemOrder.unshift(item.id);renderLibrary();renderActiveItems();}
async function loadPublishedMenu(){if(!menuDataUrl){setStatus(loadStatus,'This manager is missing its published menu address.',true);return;}if(!editor.hidden&&!window.confirm('Refreshing loads the published menu and discards unpublished changes on this page. Continue?'))return;refreshButton.disabled=true;setStatus(loadStatus,'Loading your published menu…');try{const separator=menuDataUrl.includes('?')?'&':'?';const response=await fetch(`${menuDataUrl}${separator}updated=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error('The published menu could not be loaded.');const data=readMenuData(await response.text());menuCatalogue=data.catalogue;menuCategories=data.categories;weeklySelection=new Set(data.selection);menuItemOrder=data.order;normaliseMenuState();pendingPhotos.clear();renderLibrary();renderActiveItems();editor.hidden=false;setStatus(loadStatus,'Published menu loaded. You can now make changes.');setStatus(saveStatus,'Your changes are ready to publish when you are.');}catch(error){console.error(error);setStatus(loadStatus,error.message||'Could not load the published menu.',true);}finally{refreshButton.disabled=false;}}
function prepareMenuForPublish(){syncActiveEdits();menuCatalogue.forEach(item=>{item.price=normalisePrice(item.price);});normaliseMenuState();if(!menuCatalogue.length)throw new Error('Add at least one item to your menu library before publishing.');const selection=menuItemOrder.filter(id=>weeklySelection.has(id));weeklySelection=new Set(selection);setStatus(saveStatus,`Ready to publish ${selection.length} item${selection.length===1?'':'s'} for this week.`);return selection;}

addCategoryButton.addEventListener('click',addCategory);
document.querySelector('#add-item').addEventListener('click',()=>addNewItem('top'));
document.querySelector('#add-item-bottom').addEventListener('click',()=>addNewItem('bottom'));
itemsMount.addEventListener('dragstart',event=>{if(!event.target.closest('.drag-handle'))return;const card=event.target.closest('.item-card');if(!card)return;syncActiveEdits();card.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',card.dataset.id);});
itemsMount.addEventListener('dragover',event=>{const dragging=itemsMount.querySelector('.item-card.dragging');const target=event.target.closest('.item-card');if(!dragging||!target||target===dragging)return;event.preventDefault();itemsMount.querySelectorAll('.drop-target').forEach(card=>card.classList.remove('drop-target'));target.classList.add('drop-target');const middle=target.getBoundingClientRect().top+target.offsetHeight/2;if(event.clientY<middle)target.before(dragging);else target.after(dragging);});
itemsMount.addEventListener('drop',event=>{event.preventDefault();});
itemsMount.addEventListener('dragend',event=>{const card=event.target.closest('.item-card');if(!card)return;card.classList.remove('dragging');itemsMount.querySelectorAll('.drop-target').forEach(entry=>entry.classList.remove('drop-target'));saveDragOrder();});
let touchDragCard=null;
itemsMount.addEventListener('pointerdown',event=>{if(event.pointerType!=='touch'||!event.target.closest('.drag-handle'))return;touchDragCard=event.target.closest('.item-card');if(!touchDragCard)return;syncActiveEdits();touchDragCard.classList.add('dragging');itemsMount.setPointerCapture(event.pointerId);event.preventDefault();});
itemsMount.addEventListener('pointermove',event=>{if(!touchDragCard)return;const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('.item-card');if(!target||target===touchDragCard)return;itemsMount.querySelectorAll('.drop-target').forEach(card=>card.classList.remove('drop-target'));target.classList.add('drop-target');const middle=target.getBoundingClientRect().top+target.offsetHeight/2;if(event.clientY<middle)target.before(touchDragCard);else target.after(touchDragCard);});
const finishTouchDrag=()=>{if(!touchDragCard)return;touchDragCard.classList.remove('dragging');itemsMount.querySelectorAll('.drop-target').forEach(entry=>entry.classList.remove('drop-target'));touchDragCard=null;saveDragOrder();};
itemsMount.addEventListener('pointerup',finishTouchDrag);
itemsMount.addEventListener('pointercancel',finishTouchDrag);
refreshButton.addEventListener('click',loadPublishedMenu);
document.querySelector('#menu-form').addEventListener('submit',event=>{event.preventDefault();try{prepareMenuForPublish();}catch(error){setStatus(saveStatus,error.message||'Check your menu before publishing.',true);}});
loadPublishedMenu();
